@RunWith(MockitoJUnitRunner.class)
public class ProcessProperties_enterScope_TriageGen1Test {

    private ProcessProperties processProperties;

    @Mock
    private NodeTraversal mockNodeTraversal;

    @Mock
    private Scope mockScope;

    @Mock
    private ScopeStackMock scopeStackMock;

    /**
     * Since symbolStack is likely a private field in ProcessProperties, 
     * we use reflection to inject a mock or a controlled Deque for testing.
     */
    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        processProperties = new ProcessProperties();

        // Create a dummy symbol object that has a 'scope' field
        Symbol mockSymbol = new Symbol();

        // Create a Deque to act as the symbolStack
        Deque<Symbol> stack = new ArrayDeque<>();
        stack.push(mockSymbol);

        // Use reflection to inject the stack into the processProperties instance
        Field stackField = ProcessProperties.class.getDeclaredField("symbolStack");
        stackField.setAccessible(true);
        stackField.set(processProperties, stack);
    }

    @Test
    public void enterScope_updatesScopeOfTopSymbol() {
        // Arrange
        when(mockNodeTraversal.getScope()).thenReturn(mockScope);

        // Get the symbol that was pushed in setUp via reflection
        Field stackField = ProcessProperties.class.getDeclaredField("symbolStack");
        stackField.setAccessible(true);
        Deque<Symbol> stack = (Deque<Symbol>) stackField.get(processProperties);
        Symbol topSymbol = stack.peek();

        // Act
        processProperties.enterScope(mockNodeTraversal);

        // Assert
        assertThat(topSymbol.scope).isEqualTo(mockScope);
    }

    /**
     * Inner class to mimic the structure of the Symbol class used in the original code
     * if the actual Symbol class isn't accessible or needs a mock-like behavior.
     */
    private static class Symbol {
        Scope scope;
    }

    /**
     * Interface to facilitate mocking if symbolStack is a custom class 
     * instead of a standard Deque.
     */
    private interface ScopeStackMock {
        Symbol peek();
    }
}
